package com.bank.ledger.diag;

import java.util.logging.Logger;

// Models reading pg_stat_statements / pg_stat_activity to find the ACTUAL bottleneck.
public class WriteDiagnostics {
    private static final Logger log = Logger.getLogger(WriteDiagnostics.class.getName());
    public String diagnose(long singleRowInsertsPerSec, long lockWaitMs, int connectionsUsed, int connLimit) {
        if (connectionsUsed >= connLimit)
            return "CONNECTION_PRESSURE";            // fix: PgBouncer, right-size pool
        if (lockWaitMs > 100)
            return "LOCK_CONTENTION";                // fix: shorten transactions
        if (singleRowInsertsPerSec > 1000)
            return "WRITE_AMPLIFICATION_SMALL_INSERTS"; // fix: batching
        return "VERTICAL_HEADROOM_OK";
    }
}
