package com.bank.ledger.writer;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Demonstrates naive single-row vs batched writes (models JDBC addBatch/executeBatch).
public class LedgerWriter {
    private static final Logger log = Logger.getLogger(LedgerWriter.class.getName());
    private final AtomicLong writeOps = new AtomicLong();   // proxy for WAL + round-trips

    // NAIVE: one write op (round-trip + commit + WAL) per entry.
    public void writeNaive(List<BigDecimal> amounts) {
        for (BigDecimal amt : amounts) {
            writeOps.incrementAndGet();                     // 1 op per row
        }
        log.warning(() -> "Naive wrote " + amounts.size() + " rows in " + amounts.size() + " ops");
    }

    // BATCHED: group rows into batches → far fewer write ops and less WAL.
    public void writeBatched(List<BigDecimal> amounts, int batchSize) {
        int batches = (int) Math.ceil(amounts.size() / (double) batchSize);
        for (int b = 0; b < batches; b++) writeOps.incrementAndGet(); // 1 op per batch
        log.info(() -> "Batched wrote " + amounts.size() + " rows in " + batches + " ops");
    }
    public long writeOps() { return writeOps.get(); }
    public void reset() { writeOps.set(0); }
}
