package com.bank.ledger;

import com.bank.ledger.diag.WriteDiagnostics;
import com.bank.ledger.writer.LedgerWriter;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

public class ShardingPrereqDemo {
    private static final Logger log = Logger.getLogger(ShardingPrereqDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        // Step 1: DIAGNOSE — what is actually saturated?
        WriteDiagnostics diag = new WriteDiagnostics();
        String cause = diag.diagnose(5000, 20, 10, 100);
        log.info(() -> "Diagnosis: " + cause + " (NOT a fundamental write-capacity wall)");

        // Step 2: Build 10,000 ledger inserts from the transaction logger.
        List<BigDecimal> amounts = new ArrayList<>();
        for (int i = 0; i < 10_000; i++) amounts.add(new BigDecimal("1000"));

        LedgerWriter writer = new LedgerWriter();

        // NAIVE write path.
        writer.writeNaive(amounts);
        long naiveOps = writer.writeOps();

        // Apply the BATCHING remedy (cheaper than sharding, fully reversible).
        writer.reset();
        writer.writeBatched(amounts, 500);
        long batchedOps = writer.writeOps();

        log.info(() -> "Write ops: naive=" + naiveOps + " batched=" + batchedOps
                + " → " + (naiveOps / Math.max(1, batchedOps)) + "x reduction");
        log.info("Headroom recovered WITHOUT sharding — sharding deferred");
    }
}

